input.command:
cd /home/daniel/ui-work/runs/202610271-to/sandbox/officehq-tanstack-officefloor; python3 - <<'EOF'
p='src/main/java/net/officefloor/hq/app/pool/PoolRepository.java'
s=open(p).read()
s=s.replace("""the remainder goes to the member with a cut with the largest share (the earliest added on a
     *  tie), so""","""the remainder goes to the member with the smallest non-zero cut (the latest added on a tie; a
     *  member with no cut gets none), or to the last member with a cut and a share when no cut is non-zero, so""")
old=s[s.index("        int largest = -1;"):s.index("        List<PoolMember> cut = new ArrayList<>();")]
new="""        int smallest = -1;
        int last = -1;
        for (int i = 0; i < members.size(); i++) {
            BigDecimal share = new BigDecimal(members.get(i).share());
            cuts[i] = cutting[i] ? pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN)
                    : BigDecimal.ZERO.setScale(2);
            sum = sum.add(cuts[i]);
            if (cutting[i] && share.signum() != 0) last = i;
            if (cutting[i] && cuts[i].signum() != 0
                    && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
                smallest = i;
            }
        }
        int to = smallest >= 0 ? smallest : last;
        if (to >= 0) cuts[to] = cuts[to].add(pot.subtract(sum));
"""
s=s.replace(old,new)
open(p,'w').write(s)
p='src/main/frontend/features/pools/api.ts'
s=open(p).read()
s=s.replace("the remainder going to the largest share)","the remainder going to the smallest non-zero cut, the latest added on a tie, or to the last member with a share when no cut is non-zero)")
open(p,'w').write(s)
EOF
grep -rn "largest share\|remainder" src/main/frontend --include=*.tsx | head; bin/e2e 2>&1 | tail -15

